-- Back-load the gold economy: income now tracks the weapon-cost curve, so you can
-- never afford a far-ahead weapon (fixes too-much-gold-at-L5). Pairs with the 60%
-- weapon trade-in in the store. Only money_reward changes.
update tower_floors as t set money_reward = v.m
from (values (1,1),(2,1),(3,1),(4,1),(5,3),(6,6),(7,9),(8,13),(9,16),(10,19),(11,23),(12,26),(13,29),(14,33),(15,36),(16,39),(17,43),(18,46),(19,49),(20,53),(21,56),(22,59),(23,63),(24,66),(25,69),(26,73),(27,76),(28,79),(29,83),(30,86),(31,89),(32,93),(33,96),(34,100),(35,103),(36,106),(37,110),(38,113),(39,116),(40,120),(41,123),(42,126),(43,130),(44,133),(45,136),(46,140),(47,143),(48,146),(49,150),(50,153),(51,156),(52,160),(53,163),(54,166),(55,170),(56,173),(57,176),(58,180),(59,183),(60,186),(61,190),(62,193),(63,196),(64,200),(65,203),(66,206),(67,210),(68,213),(69,216),(70,220),(71,223),(72,226),(73,230),(74,233),(75,236),(76,240),(77,243),(78,247),(79,250),(80,253),(81,257),(82,260),(83,263),(84,267),(85,270),(86,273),(87,277),(88,280),(89,283),(90,287),(91,290),(92,293),(93,297),(94,300),(95,303),(96,307),(97,310),(98,313),(99,317),(100,320)) as v(f, m)
where t.floor = v.f;
